	Vector3 Get_Position() const;
};

#define BFME_SCALE_ETH (*(const float *)0x01083B6C)

void __fastcall bfmeNormAngleETH(float &angle);

class BfmeViewETH
{
public:
	void bfmeSetAngleETH(float angle);
	void bfmeStoreAngleETH(float angle);
	void bfmeSetCamETH();
	void bfmeApplyETH(BfmeSubETH *sub);

	unsigned char m_bfmeHeadETH[0x0c];
	float m_bfmeXETH;
	float m_bfmeYETH;
	unsigned char m_bfmePadAETH[0x30];
	char m_bfmeGateETH;
	unsigned char m_bfmePadToRenderETH[0xbf];
	RenderObjClass *m_bfmeRenderETH;
	unsigned char m_bfmePadToFlagsETH[0xd4];
	char m_bfmeAETH;
	unsigned char m_bfmePadCETH[0x27];
	char m_bfmeBETH;
	unsigned char m_bfmePadDETH[0x23];
	char m_bfmeCETH;
	unsigned char m_bfmePadEETH[0x53];
	char m_bfmeDETH;
	char m_bfmeEETH;
	unsigned char m_bfmePadToSubsystemETH[0x223a];
	BfmeCameraSubsystemETH m_bfmeSubsystemETH;
};

void BfmeViewETH::bfmeSetAngleETH(float angle)
{
	if (TheGameClient->m_bfmeFlagAETH && m_bfmeGateETH)
		return;

	if (TheGameClient->m_bfmeFlagBETH && m_bfmeGateETH)
		return;

	bfmeNormAngleETH(angle);
	bfmeStoreAngleETH(angle);

	m_bfmeAETH = 0;
	m_bfmeBETH = 0;
	m_bfmeDETH = 0;
	m_bfmeCETH = 0;
	m_bfmeEETH = 0;

	bfmeSetCamETH();
	bfmeApplyETH(reinterpret_cast<BfmeSubETH *>(&m_bfmeXETH));
}

void BfmeViewETH::bfmeApplyETH(BfmeSubETH *sub)
{
	if (m_bfmeGateETH)
	{
		float dx;
		float dy;
		Vector3 pos = m_bfmeRenderETH->Get_Position();

		float a = *(const volatile float *)&m_bfmeXETH;
		float b = *(const volatile float *)&m_bfmeYETH;

		pos.Z = 0.0f;

		volatile float rx = pos.X - a;
		float ry = pos.Y - b;

		dx = rx * BFME_SCALE_ETH;
		dy = ry * BFME_SCALE_ETH;

		sub->m_bfmeXETH += dx;
		sub->m_bfmeYETH += dy;

		m_bfmeSubsystemETH.bfmeApplyETH(sub);

		sub->m_bfmeXETH -= dx;
		sub->m_bfmeYETH -= dy;
	}
}
